atan" class="form-control"></div><div class="col-md-4"><label class="form-label">Desa</label><input name="desa" class="form-control"></div><div class="col-md-4"><label class="form-label">Koordinat</label><input name="koordinat" class="form-control"></div><div class="col-md-4"><label class="form-label">Status</label><select name="status_kegiatan" class="form-select"><option>Diajukan</option><option>Dalam Pelaksanaan</option><option>Selesai</option></select></div><div class="col-12"><label class="form-label">Keterangan</label><textarea name="keterangan" class="form-control" rows="3"></textarea></div><div class="col-12"><button class="btn btn-orange">Simpan</button> <a class="btn btn-secondary" href="index.php">Batal</a></div></form></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="../../assets/js/script.js"></script></body></html>
